Here's an implementation of the `flatten_dictionary` function that uses a stack to handle nested dictionaries:

```python
from typing import Dict

class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError("Stack is empty")
        return self.items.pop()

    def is_empty(self):
        return len(self.items) == 0


def flatten_dictionary(dictionary: Dict[str, any]):

    stack = Stack()
    stack.push(("", dictionary))
    flattened_dict = {}

    while not stack.is_empty():
        prefix, nested_dict = stack.pop()

        for key, value in sorted(nested_dict.items()):
            if isinstance(value, dict):
                stack.push((prefix + key + ".", value))
            else:
                flattened_dict[prefix + key] = value

    return flattened_dict
```

