import sys

def compare_data_type_size(data_types):
    data_type_sizes = {data_type: sys.getsizeof(data_type) for data_type in data_types}
    sorted_data_type_sizes = sorted(data_type_sizes.items(), key=lambda x: x[1])
    result = {}
    for i, (data_type, size) in enumerate(sorted_data_type_sizes):
        if i == 0:
            result[data_type] = False
        else:
            prev_size = sorted_data_type_sizes[i - 1][1]
            result[data_type] = size > prev_size
    return result
```

