def fibonacci_with_cache(index: int) -> float:
    cache: Dict[int, float] = {}

    def fib(n: int) -> float:
        if n in cache:
            return cache[n]
        if n <= 1:
            result = n
        else:
            result = fib(n - 1) + fib(n - 2)
