class IntervalTreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
        self.max = value[1]

def insert_interval(root, interval):
    if root is None:
        return IntervalTreeNode(interval)
    if interval[0] <= root.value[0]:
        root.left = insert_interval(root.left, interval)
    else:
        root.right = insert_interval(root.right, interval)
        if root.max < interval[1]:
            root.max = interval[1]
    return root


def build_interval_tree(intervals):
    root = None
    for interval in intervals:
        root = insert_interval(root, interval)
    return root


def is_overlapping(root, start, end):
    if root is None:
        return False
    if root.max < start:
        return False
    if root.value[0] <= start <= root.value[1]:
        return True
    return is_overlapping(root.left, start, end) or is_overlapping(root.right, start, end)
```

