class TrieNode:
    def __init__(self):
        self.children = {}
        self.end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, string):
        node = self.root
        for char in string:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.end = True

def longest_common_substring(strings):
    trie = Trie()
    for string in strings:
        trie.insert(string)
    node = trie.root
    result = []  # Store the longest common substring
    while node and len(node.children) == 1:
        char = next(iter(node.children))  # Get the first character of the child node
        result.append(char)
        node = node.children[char]

    return "".join(result)
