class IPAddress:
    def __init__(self, ip_address: str):
        self.ip_address = ip_address
        self.binary_representation = self.get_binary_representation(ip_address)

    def get_binary_representation(self, ip_address: str) -> List[int]:
        if "." in ip_address:  # IPv4 address
            return [int(x) for x in ip_address.replace(".", "")]
        else:  # IPv6 address
            return [int(x, 16) for x in ip_address.replace(":", "")]


def match_ip_addresses(ip_addresses: List[str], network_prefixes: List[str]) -> List[str]:
    ip_addresses = [IPAddress(ip_address) for ip_address in ip_addresses]
    network_prefixes = [IPAddress(network_prefix) for network_prefix in network_prefixes]
    matches = []
    for ip in ip_addresses:
        for prefix in network_prefixes:
            if ip.binary_representation[:len(prefix.binary_representation)] == prefix.binary_representation:
                matches.append(ip.ip_address)
                break

    return matches
```

