from statistics import mean

def mean_with_missing(values):
    valid_values = [v for v in values if v is not None and not isinstance(v, str)]
    if not valid_values:
        return None
    try:
        return mean(valid_values)
    except TypeError:
        valid_values = [float(v) if isinstance(v, int) else v for v in valid_values]
        return mean(valid_values)
