def find_most_freq_chars(s):
    """
    Finds the characters in a string with the highest frequency in descending order.
    """
    char_freq = {}
    for char in s:
        if char not in char_freq:
            char_freq[char] = 1
        else:
            char_freq[char] += 1
    sorted_chars = sorted(char_freq.items(), key=lambda x: x[1], reverse=True)
    return [char for char, _ in sorted_chars]
