Here is a Python implementation of the catchment relabeling algorithm using a graph data structure and a BFS algorithm:

```python
from typing import List
class Graph:
    def __init__(self, num_vertices: int, edges: List[tuple]):
        self.adj_list = [[] for _ in range(num_vertices)]
        for u, v, w in edges:
            self.adj_list[u].append((v, w))

def catchment_relabel(N, edges, source):
    graph = Graph(N, edges)
    queue = [source]
    visited = {source}
    catchment = []
    while queue:
        current_vertex = queue.pop(0)
        catchment.append(current_vertex)
        for neighbor, _ in graph.adj_list[current_vertex]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return catchment
```

