def encode_rle(string):
    if not string or any(c.isspace() for c in string):
        raise ValueError("Invalid string")

    result = ""
    current_char = ""
    count = 0

    for i, char in enumerate(string):
        if char != current_char:
            if current_char:
                result += f"{current_char}[{count}]"
            current_char = char
            count = 0
        count += 1
