def celsius_to_fahrenheit(c):
    return 9 / 5 * c + 32

def celsius_to_kelvin(c):
    return c + 273.15

def convert_temperatures(temperatures, target_unit):
    valid_temperatures = [t for t in temperatures if isinstance(t, (int, float))]
    converted_temperatures = []

    if target_unit == "F":
        for t in valid_temperatures:
            converted_temperatures.append(celsius_to_fahrenheit(t))
        min_value = min(converted_temperatures)
        range_value = max(converted_temperatures) - min_value
        normalized_temperatures = [(t - min_value) / range_value for t in converted_temperatures]
        return normalized_temperatures
    elif target_unit == "K":
        for t in valid_temperatures:
            converted_temperatures.append(celsius_to_kelvin(t))
        return converted_temperatures
    else:
        raise ValueError("Unsupported target unit")
```

