import tarfile

def extract_tar_file(tar_file_path: str, file_name: str) -> str:
    if not tar_file_path:
        raise ValueError("Invalid tar file path")
    if not file_name:
        raise ValueError("Invalid file name")
    tar = tarfile.open(tar_file_path)
    try:
        extracted_file = tar.extractfile(file_name)
